import {heading,icon,plant,esc,target,audioButtons} from '../ui.js';
import {units,category,allItems} from '../data.js';
import {today,streak} from '../store.js';
import {startQuiz} from './study.js';
const link=(c,path)=>`#/${c.language.code}/${path}`;
export async function dashboard(c){const {store}=c,s=store.state(),l=store.lang(),code=c.language.code;const all=await category(code,'nouns');c.register(all);const cards=Object.values(l.cards),due=cards.filter(x=>x.due<=Date.now()).length,learned=cards.filter(x=>x.reps>0).length;const day=s.activity[today()]||{cards:0,seconds:0},pct=Math.min(100,(day.seconds/60)/s.settings.goal*100);const word=all.filter(x=>x.category==='nouns')[(Number(today().replaceAll('-','')))%140];const unit=Math.min(l.lastUnit||0,units.length-1),u=units[unit];const dates=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:today(d),name:d.toLocaleDateString('en',{weekday:'narrow'})};});
document.querySelector('#view').innerHTML=`${heading('A little practice. A bigger world.',`Welcome back. Let’s make a little room for ${c.language.name}.`,`<span class="date">${new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'})}</span>`)}<div class="dashboard-grid"><div><section class="hero"><div><span class="eyebrow">YOUR NEXT LITTLE ADVENTURE</span><h2>${unit===0?'Every conversation<br>starts somewhere.':esc(u[1])+'.'}</h2><p>${unit===0?'A few new words today. A whole new way to connect tomorrow.':`Keep your ${c.language.name} growing, one small lesson at a time.`}</p><a class="button" href="${link(c,'learn')}">Continue learning ${icon('arrow')}</a></div>${plant()}</section><div class="stats-row"><div class="stat"><span class="stat-icon">${icon('fire')}</span><div><strong>${streak()} <small>days</small></strong><small>Your learning streak</small></div></div><div class="stat"><span class="stat-icon">${icon('leaf')}</span><div><strong>${learned}</strong><small>Words taking root</small></div></div><div class="stat"><span class="stat-icon">${icon('star')}</span><div><strong>${s.xp} <small>XP</small></strong><small>A little progress, earned</small></div></div></div><div class="section-heading"><h2>Your learning path</h2><a href="${link(c,'learn')}">Explore the path →</a></div><div class="unit-list">${units.slice(unit,unit+3).map((x,i)=>`<div class="unit-row ${!i?'featured':''}"><span class="unit-icon">${x[2]}</span><div class="unit-copy"><h3>${esc(x[1])}${!i?'<span class="tag">UP NEXT</span>':''}</h3><p>UNIT ${unit+i+1} · ${x[0]==='basics'?'Small words, endless possibilities':esc(x[0].replace(/^./,x=>x.toUpperCase()))}</p><div class="progress"><span style="width:${Math.min(100,(l.units[x[0]]?.mastery||0)*20)}%"></span></div></div><a class="button ${i?'secondary':''}" href="${link(c,'learn')}">${i?'Explore':'Start'} ${icon('arrow')}</a></div>`).join('')}</div><div class="section-heading"><h2>A fresh way to practice</h2><a href="${link(c,'practice')}">All activities →</a></div><div class="practice-grid"><a class="practice-tile" href="${link(c,'flashcards')}"><span>▱</span><h3>Flashcards</h3><p>A little repetition, a lot of recall.</p></a><a class="practice-tile" href="${link(c,'listening')}"><span>♬</span><h3>Listen & learn</h3><p>Get an ear for the everyday.</p></a><a class="practice-tile" href="${link(c,'match')}"><span>♧</span><h3>Match the pairs</h3><p>Make a few new connections.</p></a></div></div><aside class="side-stack"><section class="card daily-card"><h3>Your daily moment <span class="muted">✧</span></h3><div class="ring"><svg viewBox="0 0 130 130" aria-label="Daily goal ${Math.round(pct)} percent"><circle cx="65" cy="65" r="55"/><circle class="fill" cx="65" cy="65" r="55" stroke-dasharray="${pct*3.456} 345.6"/></svg><div class="center"><strong>${Math.floor(day.seconds/60)}<span class="muted"> / ${s.settings.goal}</span></strong><small>MINUTES TODAY</small></div></div><p>${pct>=100?'You made time for yourself. Lovely work.':'Small steps are still steps.<br>You’ve got this.'}</p><a class="button secondary" href="${link(c,'settings')}">Adjust daily goal</a><div class="week">${dates.map(d=>`<div class="day ${s.activity[d.key]?.cards?'done':''}"><small>${d.name}</small><span>${s.activity[d.key]?.cards?'✓':'·'}</span></div>`).join('')}</div></section><section class="card word-card"><span class="eyebrow">A WORD FOR TODAY</span>${audioButtons(word.id)}<div class="target">${target(word,c.language)}</div><p class="translation">${esc(word.native)} ${word.gender?`<small>· ${esc(word.gender)}</small>`:''}</p><p class="example">Make room for one new word.<br>See where it takes you.</p><button class="button ghost" id="today-word">Add to my flashcards +</button></section><section class="card"><div class="flex between"><h3>Ready for a refresh?</h3><span>↻</span></div><p class="muted" style="font-size:12px">${due?`${due} words are ready to see you again.`:'Your memory grows with a little care. Start a deck to plant your first words.'}</p><a class="button secondary" href="${link(c,'flashcards/deck=due')}">Review due cards (${due}) →</a></section></aside></div><div class="footer-note">${icon('shield')} Your progress stays on this device. Your learning belongs to you.</div>`;
document.querySelector('#today-word').onclick=()=>{if(!l.added.includes(word.id))l.added.push(word.id);store.save();c.toast('Added to your flashcards.');};}
export async function learning(c){const all=await allItems(c.language.code);c.register(all);const l=c.store.lang();const first=l.lastUnit||0;
document.querySelector('#view').innerHTML=heading('Small steps. Real conversations.',`Your ${c.language.name} path · ${c.language.variety}`,`<a class="button secondary" href="${link(c,'placement')}">Find my starting point</a>`)+`<div class="learning-path">${!l.placement?`<div class="banner">New here? Take a short placement quiz, or begin with the first unit. <button class="button ghost" id="skip-placement">I’ll start at the beginning</button></div>`:''}${units.map((u,i)=>{const p=l.units[u[0]]||{},mastery=Math.min(5,p.mastery||0),strength=p.last?Math.max(0,100-Math.floor((Date.now()-p.last)/86400000)*3):0;return `<section class="card unit-block"><div class="unit-row"><span class="unit-icon">${u[2]}</span><div class="unit-copy"><span class="eyebrow">UNIT ${i+1} · ${i>first?'UP AHEAD':i<first?'KEEP IT GROWING':'YOUR NEXT STEP'}</span><h2>${u[1]}</h2><small>Mastery ${'♛'.repeat(mastery)}${'♧'.repeat(5-mastery)} ${p.last?`· Strength ${strength}%`:''}</small></div></div><div class="unit-detail" id="unit-${i}"><button class="button" data-lesson="${i}" ${i>first?'disabled':''}>${p.completed?'Continue':'Begin'} lesson ${icon('arrow')}</button><button class="button secondary" data-test="${i}">${i>first?'Test out & unlock':'Unit test'}</button>${p.completed?`<span class="badge">${p.completed} lessons completed</span>`:''}</div></section>`;}).join('')}</div>`;
document.querySelector('#skip-placement')?.addEventListener('click',()=>{l.placement=true;c.store.save();c.rerender();});
for(const b of document.querySelectorAll('[data-lesson],[data-test]'))b.onclick=async()=>{const i=Number(b.dataset.lesson??b.dataset.test),u=units[i];let items=await category(c.language.code,u[0]);const done=l.units[u[0]]?.completed||0;const size=10;const count=Math.max(1,Math.ceil(items.length/size));const lesson=done%count;const unitTest=b.hasAttribute('data-test');await startQuiz(c,{items:unitTest?items:items.slice(lesson*size,(lesson+1)*size),unit:u[0],unitIndex:i,unitTest,introduce:!unitTest,questionCount:unitTest?12:Math.min(10,items.slice(lesson*size,(lesson+1)*size).length),lessonCount:count});};}
export async function practice(c){const tiles=[['flashcards','▱','Flashcards','Make room in your long-term memory.'],['quiz','✦','Build a quiz','Your topics. Your pace. Your challenge.'],['spelling','✎','Spell it out','Put what you know into words.'],['listening','♬','Listen closely','Tune your ear to a new language.'],['match','♧','Make a match','Find pairs. Beat your best time.'],['challenge','☀','The daily challenge','Same date, same questions. Compare with a friend.'],['alphabet','Aa','Alphabet & sounds','Get to know the building blocks.'],['grammar','☷','Grammar notes','Little explanations that make things click.'],['decks','▤','Your own decks','Collect the words that matter to you.'],['dialogues','☏','Small conversations','Practice one side of a real-life exchange.'],['reader','▥','Tap-to-translate reader','Bring a little text of your own.']];document.querySelector('#view').innerHTML=heading('Keep it interesting.',`A different way to grow your ${c.language.name}, every day.`)+`<div class="grid3">${tiles.map(([path,emoji,title,desc])=>`<a class="practice-tile" href="${link(c,path)}"><span>${emoji}</span><h2>${title}</h2><p>${desc}</p></a>`).join('')}</div>`;}
export async function stats(c){const s=c.store.state(),l=c.store.lang(),all=await allItems(c.language.code);c.register(all);const cards=Object.values(l.cards),learned=cards.filter(x=>x.reps).length,mastered=cards.filter(x=>x.interval>=21).length,accuracy=l.history.length?Math.round(l.history.filter(x=>x.correct).length/l.history.length*100):0;const totalSeconds=Object.values(s.activity).reduce((a,b)=>a+(b.seconds||0),0);const days=Array.from({length:90},(_,i)=>{const d=new Date();d.setDate(d.getDate()-89+i);return today(d);});const hard=Object.entries(l.cards).sort((a,b)=>b[1].lapses-a[1].lapses).filter(x=>x[1].lapses).slice(0,5);const achievements=[['🌱','First lesson',Object.values(l.units).some(x=>x.completed)],['🔥','7-day streak',streak()>=7],['🌳','100 words',learned>=100],['✦','Perfect lesson',l.perfect],['☾','Night owl',l.history.some(x=>new Date(x.at).getHours()>=22)],['Aa','Alphabet explorer',l.alphabetExplored]];
document.querySelector('#view').innerHTML=heading('Look how far you’ve come.',`Every little practice adds up. Your ${c.language.name} story so far.`)+`<div class="stats-row"><div class="stat"><div><strong>${learned}</strong><small>Words learned · ${mastered} mastered</small></div></div><div class="stat"><div><strong>${accuracy}%</strong><small>Answer accuracy</small></div></div><div class="stat"><div><strong>${Math.floor(totalSeconds/60)} min</strong><small>Time spent growing</small></div></div></div><div class="grid2" style="margin-top:20px"><section class="card"><h2>Your little moments</h2><p class="muted">Study activity · last 90 days</p><div class="heatmap">${days.map(d=>`<span class="${s.activity[d]?.cards?'filled':''}" title="${d}: ${s.activity[d]?.cards||0} answers" aria-label="${d}: ${s.activity[d]?.cards||0} answers"></span>`).join('')}</div><div class="bar-chart">${days.slice(-7).map(d=>`<div class="bar-col"><span style="height:${Math.min(95,(s.activity[d]?.cards||0)*4)}px" title="${s.activity[d]?.cards||0} cards"></span><small>${new Date(d+'T12:00:00').toLocaleDateString('en',{weekday:'short'})}</small></div>`).join('')}</div></section><section class="card"><h2>A few milestones</h2><div class="grid2">${achievements.map(([emoji,name,done])=>`<div class="stat ${done?'selected':''}"><span>${emoji}</span><div>${name}<small style="display:block">${done?'Earned':'Still growing'}</small></div></div>`).join('')}</div><p class="muted" style="margin-top:18px">${s.freeze} earned streak freezes · 1 per 500 XP</p><button class="button secondary" id="freeze">Use a freeze for yesterday</button></section><section class="card"><h2>Words worth revisiting</h2>${hard.length?hard.map(([id,p])=>{const w=all.find(x=>x.id===id);return w?`<p>${target(w,c.language)} · ${esc(w.native)} <small>${p.lapses} lapses</small> ${audioButtons(id)}</p>`:'';}).join(''):'<p class="muted">Nothing here yet. Your trickiest words will find their way here.</p>'}<a class="button secondary" href="${link(c,'flashcards/deck=mistakes')}">Practice mistakes</a></section><section class="card"><h2>Every language, a new door</h2>${c.languages.map(language=>{const progress=c.store.lang(language.code);return `<p>${language.flag} ${language.name} <strong>${Object.values(progress.cards).filter(x=>x.reps).length}</strong> words learned</p>`;}).join('')}<button class="button" id="scorecard">Export a scorecard</button><p class="muted"><small>Share the downloaded text with your friend. No accounts, no leaderboard, just encouragement.</small></p></section></div><section class="card" style="margin-top:20px"><h2>Where you’re growing</h2>${units.map(u=>{const ids=all.filter(x=>x.category===u[0]).map(x=>x.id),h=l.history.filter(x=>ids.includes(x.id));return `<div class="setting"><span>${u[1]}</span><span>${h.length?Math.round(h.filter(x=>x.correct).length/h.length*100)+'% accuracy':'No practice yet'}</span></div>`;}).join('')}</section>`;
document.querySelector('#scorecard').onclick=()=>c.store.download('parola-scorecard.txt',`PAROLA · ${today()}\n${c.language.name}\n${s.xp} XP · ${streak()} day streak\n${learned} words learned · ${accuracy}% accuracy\nDaily challenge: ${l.challenge?.date===today()?l.challenge.score:'not played today'}`,'text/plain');document.querySelector('#freeze').onclick=()=>{const d=new Date();d.setDate(d.getDate()-1);const key=today(d);if(!s.freeze)return c.toast('Earn a freeze with 500 XP.');if(s.activity[key]?.cards)return c.toast('Yesterday is already covered.');s.activity[key]={cards:1,xp:0,seconds:0,frozen:true};s.freeze--;c.store.save();c.toast('Yesterday is covered. Keep your streak growing.');c.rerender();};}
